  "implementation": "def solve(case):
    import json
    nodes = case.get('nodes')
    required_symbols = set(case.get('required_symbols', []))
    if not nodes:
        raise ValueError('Missing nodes')
    if not required_symbols:
        raise ValueError('Missing required_symbols')
    # build maps
    node_map = {}
    children_map = {}
    root_id = None
    for n in nodes:
        nid = n.get('id')
        if not nid or not isinstance(nid, str):
            raise ValueError('Invalid node id')
        node_map[nid] = n
        parent = n.get('parent')
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            children_map.setdefault(parent, []).append(nid)
    if root_id is None:
        raise ValueError('No root node')
    # validate required symbols exist initially
    symbol_set = set(n['symbol'] for n in nodes)
    for sym in required_symbols:
        if sym not in symbol_set:
            raise ValueError(f'Required symbol {sym} not found')
    # sort nodes by depth descending, then id ascending for stable tie
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained = set(node_map.keys())
    removed = []
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if nid == root_id:
            continue
        # check retained children
        has_retained_child = any(cid in retained for cid in children_map.get(nid, []))
        if has_retained_child:
            continue
        # simulate removal to check required symbols
        retained.remove(nid)
        # check all required symbols still present
        missing = False
        for sym in required_symbols:
            found = any(node_map[r]['symbol'] == sym for r in retained)
            if not found:
                missing = True
                break
        if missing:
            retained.add(nid)   # restore
        else:
            removed.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"
